using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
static class SuiteArt {
 public static Icon AppIcon(){try{return Icon.ExtractAssociatedIcon(Application.ExecutablePath)??SystemIcons.Application;}catch{return SystemIcons.Application;}}
 public static Image Badge(int size){var bitmap=new Bitmap(size,size);using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/128f,size/128f);g.Clear(Color.Transparent);using(var path=new GraphicsPath()){path.AddArc(4,4,36,36,180,90);path.AddArc(88,4,36,36,270,90);path.AddArc(88,88,36,36,0,90);path.AddArc(4,88,36,36,90,90);path.CloseFigure();using(var fill=new LinearGradientBrush(new Point(0,0),new Point(128,128),Color.FromArgb(34,56,87),Color.FromArgb(17,24,42)))g.FillPath(fill,path);using(var stroke=new Pen(Color.FromArgb(83,111,151),2))g.DrawPath(stroke,path);}PointF[] points={new PointF(64,18),new PointF(76,49),new PointF(107,64),new PointF(76,77),new PointF(64,110),new PointF(51,77),new PointF(20,64),new PointF(51,49)};using(var fill=new LinearGradientBrush(new Point(25,25),new Point(100,105),Color.FromArgb(108,230,236),Color.FromArgb(171,155,255)))g.FillPolygon(fill,points);using(var fill=new SolidBrush(Color.FromArgb(235,247,255)))g.FillEllipse(fill,58,58,12,12);}return bitmap;}
}
